WITH reports AS MATERIALIZED (SELECT patient,lower(json_extract(payload,'$.medication_name_reported')) AS drug,json_extract(payload,'$.use_statement') AS use_state FROM records WHERE stream='reported_medication_entries') SELECT DISTINCT a.patient AS patient_id FROM reports a JOIN reports b ON a.patient=b.patient AND a.drug=b.drug WHERE a.use_state='reports_taking' AND b.use_state='reports_not_taking' ORDER BY patient_id;
